import { type ConjugatedForm, conjugateVerb } from "@/lib/conjugation"
import type {
  ConjugationType,
  Register,
  Scene,
  VerbConjugation,
  VerbEntry,
  VerbGroup,
} from "./types"

type TokenPart = readonly [text: string, kana?: string]

type PassiveVerbSeed = {
  id: string
  dictionaryForm: string
  verbGroup: VerbGroup
  meaningZh: string
  conjugatedForm: string
  explanationZh: string
  patternHint: string
  parts: TokenPart[]
  chinese: string
  scene: Scene
  register: Register
}

function makePassiveVerbEntries(seeds: PassiveVerbSeed[]): VerbEntry[] {
  return seeds.map(
    ({
      id,
      dictionaryForm,
      verbGroup,
      meaningZh,
      conjugatedForm,
      explanationZh,
      patternHint,
      parts,
      chinese,
      scene,
      register,
    }) => ({
      id,
      dictionaryForm,
      verbGroup,
      meaningZh,
      conjugations: [
        {
          conjugationType: "passive",
          conjugatedForm,
          explanationZh,
          patternHint,
          examples: [
            {
              japanese: parts.map(([text]) => text).join(""),
              tokens: parts.map(([text, kana]) => (kana ? { text, kana } : { text })),
              kana: parts.map(([text, kana]) => kana ?? text).join(""),
              chinese,
              scene,
              register,
            },
          ],
        },
      ],
    }),
  )
}

const CORE_CONJUGATION_TYPES = ["polite", "potential", "negative"] as const
type CoreConjugationType = (typeof CORE_CONJUGATION_TYPES)[number]

const FORM_EXAMPLE_TEXT: Record<
  CoreConjugationType,
  { lead: string; chineseLead: string; register: Register; scene: Scene }
> = {
  polite: { lead: "あとで", chineseLead: "稍后会", register: "丁寧", scene: "work" },
  potential: { lead: "いまなら", chineseLead: "现在的话能", register: "カジュアル", scene: "life" },
  negative: { lead: "きょうは", chineseLead: "今天不", register: "カジュアル", scene: "life" },
}

const CORE_EXAMPLE_OVERRIDES: Partial<
  Record<
    string,
    Partial<
      Record<
        CoreConjugationType,
        { lead: string; chinese: string; scene?: Scene; register?: Register }
      >
    >
  >
> = {
  shinu: {
    polite: { lead: "このむしはすぐ", chinese: "这只虫子很快会死。" },
    potential: { lead: "そんなことで", chinese: "不会因为那点事就能死。" },
    negative: { lead: "まだ", chinese: "还不会死。" },
  },
  furuRain: {
    polite: { lead: "このあとあめが", chinese: "之后会下雨。" },
    potential: { lead: "かたちとしては", chinese: "形式上能变成这个可能形。" },
    negative: { lead: "きょうはあめが", chinese: "今天不会下雨。" },
  },
  kowareru: {
    polite: { lead: "このままだと", chinese: "这样下去会坏掉。" },
    potential: { lead: "かたちとしては", chinese: "形式上能变成这个可能形。" },
    negative: { lead: "まだ", chinese: "还不会坏。" },
  },
}

function withCoreConjugations(entries: VerbEntry[]): VerbEntry[] {
  return entries.map((entry) => {
    const existingTypes = new Set<ConjugationType>(
      entry.conjugations.map((conj) => conj.conjugationType),
    )
    const additions = CORE_CONJUGATION_TYPES.filter((type) => !existingTypes.has(type)).map(
      (type) => makeCoreConjugation(entry, type),
    )
    if (additions.length === 0) return entry
    return { ...entry, conjugations: [...entry.conjugations, ...additions] }
  })
}

function makeCoreConjugation(entry: VerbEntry, type: CoreConjugationType): VerbConjugation {
  const form = conjugateCore(entry, type)
  const defaults = FORM_EXAMPLE_TEXT[type]
  const override = CORE_EXAMPLE_OVERRIDES[entry.id]?.[type]
  const lead = override?.lead ?? defaults.lead
  const chinese = override?.chinese ?? `${defaults.chineseLead}${entry.meaningZh}。`
  return {
    conjugationType: type,
    conjugatedForm: form.text,
    explanationZh: getCoreExplanation(type),
    patternHint: getCorePatternHint(entry, type),
    examples: [
      {
        japanese: `${lead}${form.text}。`,
        tokens: [{ text: lead }, { text: form.text, kana: form.kana }, { text: "。" }],
        kana: `${lead}${form.kana}。`,
        chinese,
        scene: override?.scene ?? defaults.scene,
        register: override?.register ?? defaults.register,
      },
    ],
  }
}

function conjugateCore(entry: VerbEntry, type: CoreConjugationType): ConjugatedForm {
  const { dictionaryForm, verbGroup } = entry
  const kana = getDictionaryKana(entry)
  const forms = conjugateVerb(dictionaryForm, kana, verbGroup)
  switch (type) {
    case "polite":
      return forms.masu
    case "potential":
      return forms.potential
    case "negative":
      return forms.nai
  }
}

/** 从例句 token 里反查辞書形的假名读法，喂给 lib/conjugation 的活用函数。 */
function getDictionaryKana(entry: VerbEntry): string {
  const { dictionaryForm, verbGroup } = entry
  if (dictionaryForm === "来る") return "くる"
  if (dictionaryForm === "する") return "する"
  const readingMap = buildReadingMap(entry)
  if (verbGroup === "group3" && dictionaryForm.endsWith("する")) {
    return `${getReadingForText(dictionaryForm.slice(0, -2), readingMap)}する`
  }
  const tail = dictionaryForm.slice(-1)
  return `${getReadingForText(dictionaryForm.slice(0, -1), readingMap)}${tail}`
}

function buildReadingMap(entry: VerbEntry): Map<string, string> {
  const map = new Map<string, string>()
  for (const conjugation of entry.conjugations) {
    for (const example of conjugation.examples) {
      for (const token of example.tokens) {
        if (token.kana) map.set(token.text, token.kana)
      }
    }
  }
  return map
}

function getReadingForText(text: string, readingMap: Map<string, string>): string {
  let output = ""
  let index = 0
  const keys = [...readingMap.keys()].sort((a, b) => b.length - a.length)
  while (index < text.length) {
    const match = keys.find((key) => text.startsWith(key, index))
    if (match) {
      output += readingMap.get(match)
      index += match.length
    } else {
      output += text[index]
      index += 1
    }
  }
  return output
}

function getCoreExplanation(type: CoreConjugationType): string {
  switch (type) {
    case "polite":
      return "ます形；丁寧に述べる形"
    case "potential":
      return "可能形；できることを表す形"
    case "negative":
      return "ない形；しないことを表す形"
  }
}

function getCorePatternHint(entry: VerbEntry, type: CoreConjugationType): string {
  if (entry.dictionaryForm === "来る") {
    switch (type) {
      case "polite":
        return "三类：来る → 来ます（きます）"
      case "potential":
        return "三类：来る → 来られる（こられる）"
      case "negative":
        return "三类：来る → 来ない（こない）"
    }
  }
  if (entry.dictionaryForm === "する") {
    switch (type) {
      case "polite":
        return "三类：する → します"
      case "potential":
        return "三类：する → できる"
      case "negative":
        return "三类：する → しない"
    }
  }
  if (entry.verbGroup === "group3") {
    switch (type) {
      case "polite":
        return "三类：〜する → 〜します"
      case "potential":
        return "三类：〜する → 〜できる"
      case "negative":
        return "三类：〜する → 〜しない"
    }
  }
  if (entry.verbGroup === "group2") {
    switch (type) {
      case "polite":
        return "二类：語幹 + ます"
      case "potential":
        return "二类：語幹 + られる"
      case "negative":
        return "二类：語幹 + ない"
    }
  }
  switch (type) {
    case "polite":
      return "一类：う段 → い段 + ます"
    case "potential":
      return "一类：う段 → え段 + る"
    case "negative":
      return "一类：う段 → あ段 + ない（う → わない）"
  }
}

